	('f2d045a4-9dc5-4904-b80e-a0bc32a01e14', '39a60449-21d2-47e4-b5f1-9a3dd42eb096', '316744be-08b6-49b9-9ba6-985e877fdb02', 'Nadia Salsabila', 'Nadia', 'P', 'Padang', '2007-04-23', '+6283181226066', 'Belum Diisi', 'Perumahan hijau daun blok D no 3,jalan SMP 21 padang, ulu gadut', 'Belum Diisi', 'Belum Diisi', 2025, 'Saya ingin ikut UKM Robotik yang pertama karna saya sangat tertarik dengan hal hal kreatif menciptakan sesuatu yang bermanfaat selain itu saya juga ingin mendapatkan ilmu yang sesuai dengan prodi yang saya pelajari di D3 Teknik Elektronika dan bisa langsung saya terapkan. Lewat UKM ini saya bisa belajar lebih banyak hal secara praktik, bukan cuma teori, sambil mengembangkan kreativits. Selain itu, saya juga ingin nambah pengalaman dan juga relasi. Yang nggak kalah penting, saya ingin belajar kerja sama tim, dan mengasah kemampuan diri saya agar makin siap di dunia teknik elektronika.', '-', '-', 'https://mvorotvbainhtppatvnb.supabase.co/storage/v1/object/public/pendaftaran/upload/Ac6DeUo2arXNGwHYQ27cKgGijFt2_pasFoto_1756955136315_inbound3932105149292075370.jpg', NULL, 'https://mvorotvbainhtppatvnb.supabase.co/storage/v1/object/public/pendaftaran/upload/Ac6DeUo2arXNGwHYQ27cKgGijFt2_igRobotik_1756955137655_inbound6276389348864069203.jpg', 'https://mvorotvbainhtppatvnb.supabase.co/storage/v1/object/public/pendaftaran/upload/Ac6DeUo2arXNGwHYQ27cKgGijFt2_igMrc_1756955138447_inbound2568240200712273276.jpg', 'https://mvorotvbainhtppatvnb.supabase.co/storage/v1/object/public/pendaftaran/upload/Ac6DeUo2arXNGwHYQ27cKgGijFt2_youtube_1756955138802_inbound344068939059796865.jpg', 'https://mvorotvbainhtppatvnb.supabase.co/storage/v1/object/public/pendaftaran/upload/Ac6DeUo2arXNGwHYQ27cKgGijFt2_1756955154914_inbound8934725799203858166.jpg', 'transfer', 'verified', '2025-09-04 02:51:37.361+00', '2026-06-15 02:36:41.012137+00', NULL, NULL),
