INSERT INTO "public"."divisions" ("id", "name", "description", "created_at", "slug", "short_description", "badge_label", "badge_color", "accent_color", "sort_order", "is_active", "tags") VALUES
	('5a1995dd-635e-411f-898e-15353d60c8ca', 'KRAI', 'Kontes Robot ABU Indonesia (KRAI) adalah kompetisi robot tingkat Asia-Pasifik yang menuntut perancangan robot bertugas menyelesaikan misi tertentu dalam sebuah arena. Tantangan utama meliputi kontrol otomatis presisi tinggi, navigasi lapangan tanpa kesalahan, dan strategi koordinasi antar robot.', '2026-06-23 15:03:41.927606+00', 'krai', 'Robot beroda maupun berkaki yang bertempur dalam arena ABU Robocon — tantangan teknis tertinggi di skala Asia.', 'Flagship', '#E22718', '#E22718', 1, true, '["Kontrol Otomatis", "Navigasi Lapangan", "Strategi Tim"]'),
	('9c687745-1b13-44cd-9455-3acac8b2e1b3', 'KRSBI-B', 'Kontes Robot Sepak Bola Indonesia Beroda (KRSBI-B) mempertandingkan tim robot beroda dalam permainan sepak bola. Fokus utama divisi ini adalah pengembangan computer vision untuk deteksi objek secara real-time, sistem locomosi yang lincah, dan pengendalian bola yang akurat.', '2026-06-23 15:03:41.927606+00', 'krsbi-b', 'Robot beroda yang bermain sepak bola sesungguhnya, dengan sistem visi komputer dan koordinasi tim real-time.', 'Populer', '#1C69D4', '#1C69D4', 2, true, '["Computer Vision", "Locomotion", "Ball Control"]'),
	('77167aea-eedb-477c-a4ab-8b9538077ab2', 'KRSBI-H', 'Kontes Robot Sepak Bola Indonesia Humanoid (KRSBI-H) menantang tim untuk membangun robot bipedal yang bisa berjalan, menendang bola, dan bermain dalam format tim. Tantangan terbesar ada pada penyeimbangan dinamis (balance control), pola langkah (gait), dan pengambilan keputusan otonom di lapangan.', '2026-06-23 15:03:41.927606+00', 'krsbi-h', 'Robot humanoid bipedal yang bergerak layaknya manusia dan bertanding dalam pertandingan sepak bola 5 lawan 5.', 'Humanoid', '#0066B1', '#0066B1', 3, true, '["Bipedal Walking", "Balance Control", "AI Decision"]'),
	('ad649bf4-f483-4bee-b0b1-0468cb076aae', 'KRSTI', 'Kontes Robot Seni Tari Indonesia (KRSTI) menggabungkan teknologi tinggi dengan kekayaan budaya. Robot humanoid dirancang untuk menari sesuai koreografi tari tradisional Indonesia dengan tingkat presisi dan sinkronisasi terhadap musik yang sangat tinggi.', '2026-06-23 15:03:41.927606+00', 'krsti', 'Robot humanoid yang menarikan tari tradisional Indonesia dengan sinkronisasi musik dan gerakan presisi milimeter.', 'Budaya', '#1C69D4', '#1C69D4', 4, true, '["Motion Planning", "Rhythm Sync", "Servo Control"]'),
	('69a82c90-a78f-48a7-82f3-1e6b6b46e757', 'KRSRI', 'Kontes Robot SAR Indonesia (KRSRI) mensimulasikan misi Search and Rescue. Robot harus mampu menjelajahi medan yang menyerupai lokasi bencana, mendeteksi korban, dan memberikan pertolongan secara otonom. Teknologi utama yang digunakan adalah SLAM, sensor fusion, dan navigasi otonom.', '2026-06-23 15:03:41.927606+00', 'krsri', 'Robot pencari dan penyelamat korban bencana — mensimulasikan operasi SAR nyata di medan rusak dan berantakan.', 'SAR', '#E22718', '#E22718', 5, true, '["SLAM Navigation", "Sensor Fusion", "Autonomous SAR"]');
INSERT INTO "public"."achievements" ("id", "title", "year", "level", "division_id", "description", "created_at") VALUES
	('0becf501-8092-41d7-98ba-2c3a2756b116', 'Design dan Konstruksi Terbaik KRI tingkat Regional I Sumatera', 2010, 'Regional', '5a1995dd-635e-411f-898e-15353d60c8ca', 'Penghargaan eksklusif atas keunggulan perancangan mekanik, kekuatan struktural, dan inovasi fabrikasi robot pada divisi utama Kontes Robot Indonesia (KRI) Regional I.', '2026-07-04 13:17:10.777297+00'),
	('df3f0266-fe34-4aaa-a874-519413e860cf', 'Peringkat VII se-Indonesia, Pemadam Api Beroda', 2010, 'Nasional', '69a82c90-a78f-48a7-82f3-1e6b6b46e757', 'Keberhasilan menembus peringkat 7 besar tingkat nasional dalam kategori robot cerdas pemadam api beroda berkat efisiensi algoritma penelusuran labirin (maze-solving).', '2026-07-04 13:17:10.777297+00'),
	('5d71898a-bb8d-42e4-822b-07197b438203', 'Peringkat Sepuluh Besar KRI se-Indonesia di UI', 2010, 'Nasional', '5a1995dd-635e-411f-898e-15353d60c8ca', 'Prestasi tingkat nasional dengan menempati jajaran 10 besar pada Kontes Robot Indonesia (KRI) yang diselenggarakan di Universitas Indonesia (UI).', '2026-07-04 13:17:10.777297+00'),
	('272718e8-7f25-492b-b7f3-5621cbb8e2b3', 'Juara I Lomba Robot di Stand ITS pada PIMNAS XVIII', 2010, 'Nasional', NULL, 'Meraih peringkat pertama dalam kompetisi robotika yang diadakan di stand Institut Teknologi Sepuluh Nopember (ITS) pada pergelaran akbar PIMNAS XVIII.', '2026-07-04 13:17:10.777297+00'),
	('c385627a-5190-4702-932f-e001d173e292', 'Juara I Lomba Robot Line Tracer Program dan Non Program se-Kota Padang', 2010, 'Lokal', NULL, 'Dominasi total tim robotika dengan menyabet podium pertama sekaligus di dua kategori utama (programmed & non-programmed) robot pengikut garis se-Kota Padang.', '2026-07-04 13:17:10.777297+00'),
	('229625fa-9553-4c24-94f1-3ccb0fe92f88', 'Juara 3 Automatic Robot Contest (ARCON) se-Indonesia', 2010, 'Nasional', NULL, 'Keberhasilan meraih posisi ketiga dalam ajang kompetisi robot otomatis tingkat nasional (ARCON) yang diikuti oleh berbagai perguruan tinggi ternama.', '2026-07-04 13:17:10.777297+00'),
	('8e488f16-bf44-4ae8-834f-60939dd6d68e', 'Juara 1 Kontes Robot Cerdas Indonesia (KRCI) Divisi Battle Tingkat Regional 1 Sumatra', 2011, 'Regional', '9c687745-1b13-44cd-9455-3acac8b2e1b3', 'Meraih gelar juara utama di tingkat regional dalam divisi robot sepak bola beroda (KRCI Battle), yang menjadi fondasi awal perkembangan tim KRSBI Beroda.', '2026-07-04 13:17:10.777297+00'),
	('d495d2b1-0e22-4cfa-900d-06466473a09f', 'Juara Harapan 1 Kontes Robot Cerdas Indonesia (KRCI) Pemadam Api Divisi Berkaki Regional 1 Sumatra', 2011, 'Regional', '69a82c90-a78f-48a7-82f3-1e6b6b46e757', 'Meraih posisi harapan pertama dalam kategori robot otonom berkaki yang dirancang khusus untuk melewati rintangan kompleks demi memadamkan titik api.', '2026-07-04 13:17:10.777297+00'),
	('272a043a-ce3e-4dba-8418-222fe720a2dd', 'Best Design Humanoid Robot Soccer', 2011, 'Nasional', '77167aea-eedb-477c-a4ab-8b9538077ab2', 'Apresiasi tingkat nasional atas arsitektur mekanik, penyeimbangan dinamis (balance control), dan estetika rancangan robot sepak bola berkaki (humanoid).', '2026-07-04 13:17:10.777297+00'),
	('c86079ee-4477-4a34-b087-d8923aaa15bc', '8 Besar Kontes Robot Seni Indonesia (KRSI) di UGM', 2011, 'Nasional', 'ad649bf4-f483-4bee-b0b1-0468cb076aae', 'Menembus persaingan elite 8 besar nasional pada Kontes Robot Seni Indonesia (KRSI) yang diadakan di Universitas Gadjah Mada (UGM).', '2026-07-04 13:17:10.777297+00'),
	('f8d9f79d-8170-4877-879f-cf5ece6d010f', 'Juara 1, 2, dan 3 pada Minangkabau Robot Contest se-Indonesia (MRC)', 2011, 'Nasional', NULL, 'Sapu bersih seluruh podium juara (Juara 1, 2, dan 3) oleh delegasi tim robotika PNP dalam ajang turnamen terbuka Minangkabau Robot Contest.', '2026-07-04 13:17:10.777297+00'),
	('3d276739-a99c-45ba-93a1-885d6451c8fe', 'Juara 2 Kontes Robot Soccer Indonesia Regional 1 di Medan', 2012, 'Regional', '9c687745-1b13-44cd-9455-3acac8b2e1b3', 'Meraih predikat runner-up regional wilayah Sumatera pada kompetisi taktis sepak bola robot beroda yang diselenggarakan di Kota Medan.', '2026-07-04 13:17:10.777297+00'),
	('bf522015-4d73-4eae-9fec-0804d8adb52e', 'Juara Harapan 1 Kontes Robot Cerdas Indonesia (KRCI) Divisi Beroda Pemadam Api Regional I Sumatera', 2012, 'Regional', '69a82c90-a78f-48a7-82f3-1e6b6b46e757', 'Mengamankan peringkat harapan pertama di Regional I Sumatera untuk kategori robot cerdas pemadam api berbasis penggerak roda (wheeled).', '2026-07-04 13:17:10.777297+00'),
	('f538af40-a24f-4a6d-869a-741d7d6fcc12', 'Masuk 8 besar Kontes Robot Soccer Indonesia Nasional di ITB Bandung', 2012, 'Nasional', '9c687745-1b13-44cd-9455-3acac8b2e1b3', 'Menembus babak perempat final (8 besar) tingkat nasional dalam kompetisi robot soccer beroda yang berlangsung ketat di Institut Teknologi Bandung (ITB).', '2026-07-04 13:17:10.777297+00'),
	('91519328-da62-43a5-9a44-a52da34570a8', 'Juara 2 KRI pada Kontest Robot Nasional Regional 1 Sumatera di Lampung', 2013, 'Regional', '5a1995dd-635e-411f-898e-15353d60c8ca', 'Meraih posisi kedua (Juara 2) di tingkat Regional 1 Sumatera pada divisi robot otomatis KRI yang dipusatkan di Lampung.', '2026-07-04 13:17:10.777297+00'),
	('2cf94b2e-bd82-4486-b3ff-c6c74616f119', 'Juara 3 KRSI pada Kontest Robot Nasional Regional 1 Sumatera di Lampung', 2013, 'Regional', 'ad649bf4-f483-4bee-b0b1-0468cb076aae', 'Menduduki peringkat ketiga regional dalam kategori robot seni penari yang menuntut sinkronisasi tinggi terhadap musik tradisional.', '2026-07-04 13:17:10.777297+00'),
	('bf0b1aa2-971a-45da-80ab-8262654b7d0a', 'Juara Harapan 1 KRSBI pada Kontest Robot Nasional Regional 1 Sumatera di Lampung', 2013, 'Regional', '9c687745-1b13-44cd-9455-3acac8b2e1b3', 'Mengamankan peringkat harapan pertama pada babak kualifikasi regional wilayah Sumatera untuk kompetisi robot sepak bola beroda.', '2026-07-04 13:17:10.777297+00'),
	('387e3549-d69f-4fc0-82fb-c9958c679f98', 'Design KRI Terbaik pada Kontest Robot Nasional Regional 1 Sumatera di Lampung', 2013, 'Regional', '5a1995dd-635e-411f-898e-15353d60c8ca', 'Penghargaan prestisius atas inovasi mekanikal dan rancang bangun sistem aktuator terbaik pada robot divisi KRI di Regional 1.', '2026-07-04 13:17:10.777297+00'),
	('53bb1e60-abae-4a25-bc4d-5d9e82af99fd', 'Inovasi Terbaik KRPAI Berkaki pada Kontest Robot Nasional Regional 1 Sumatera di Lampung', 2013, 'Regional', '69a82c90-a78f-48a7-82f3-1e6b6b46e757', 'Apresiasi atas terobosan teknologi sistem sensor deteksi panas atau mekanisme pergerakan kaki (gait) pada robot pemadam api.', '2026-07-04 13:17:10.777297+00'),
	('52cf68b3-1e4d-4101-97ca-e382fb53f7ea', 'Juara Harapan 1 KRAI Regional 1 Sumatera', 2014, 'Regional', '5a1995dd-635e-411f-898e-15353d60c8ca', 'Mempertahankan konsistensi di papan atas regional dengan meraih peringkat harapan 1 pada divisi utama Kontes Robot ABU Indonesia (KRAI).', '2026-07-04 13:17:10.777297+00'),
