	('f620402e-4f57-434a-a684-2c8d85c93a33', 'Juara 1 KRSBI Regional 1 Sumatera', 2014, 'Regional', '9c687745-1b13-44cd-9455-3acac8b2e1b3', 'Menjadi juara utama se-Sumatera dalam kompetisi taktis sepak bola robot beroda berkat keunggulan strategi computer vision dan penguasaan bola.', '2026-07-04 13:17:10.777297+00'),
