	('8e1504fb-b786-4fb2-84c7-5a5bd1611b03', 'Juara Harapan 1 Desain Terbaik KRPAI Regional 1 Sumatera', 2017, 'Regional', '69a82c90-a78f-48a7-82f3-1e6b6b46e757', 'Meraih peringkat harapan pertama sekaligus apresiasi tinggi atas efisiensi desain rancang bangun fisik dan penempatan sensor robot pemadam api.', '2026-07-04 13:17:10.777297+00'),
	('87b67f61-2621-4088-a768-01f8dfbbf66b', 'Juara 1 KRSTI Regional 1 Sumatera', 2017, 'Regional', 'ad649bf4-f483-4bee-b0b1-0468cb076aae', 'Keberhasilan mempertahankan gelar Juara 1 tingkat Regional 1 Sumatera secara berturut-turut pada kategori Kontes Robot Seni Tari Indonesia.', '2026-07-04 13:17:10.777297+00'),
	('edc77f75-340d-47c9-94a1-6c27b4087d62', 'Juara 3 KRSBI Beroda Tingkat Regional', 2017, 'Regional', '9c687745-1b13-44cd-9455-3acac8b2e1b3', 'Meraih posisi ketiga dalam kompetisi robot sepak bola beroda tingkat regional dengan implementasi kemajuan signifikan pada sistem roda omni-directional.', '2026-07-04 13:17:10.777297+00'),
	('f0c37e9f-2c96-4359-a40a-f247782711bb', 'Juara 1 Design Terbaik KRPAI Berkaki Regional 1 Sumatera', 2018, 'Regional', '69a82c90-a78f-48a7-82f3-1e6b6b46e757', 'Penghargaan tertinggi atas konstruksi mekanis, keandalan pergerakan otonom berkaki, dan keindahan estetika robot pemadam api se-Sumatera.', '2026-07-04 13:17:10.777297+00'),
	('c14d16f0-377d-4bb4-b4fd-9d62c39016a2', 'Juara Harapan KRPAI Regional 1 Sumatera', 2018, 'Regional', '69a82c90-a78f-48a7-82f3-1e6b6b46e757', 'Mengamankan posisi juara harapan pada kompetisi pencarian korban dan pemadaman api otonom yang berlangsung kompetitif di wilayah Sumatera.', '2026-07-04 13:17:10.777297+00'),
	('fb0c816a-cccc-4f12-8fe4-424bd4edaeca', 'Juara 2 KRSBI Beroda Regional 1 Sumatera', 2018, 'Regional', '9c687745-1b13-44cd-9455-3acac8b2e1b3', 'Menempati peringkat kedua di Regional 1 Sumatera setelah menunjukkan performa kerja sama tim robot dan akurasi tendangan yang luar biasa.', '2026-07-04 13:17:10.777297+00'),
