	('39231c83-fb80-4b6f-9039-ffd465e586de', 'Juara 3 KRSBI Humanoid Tingkat Regional di Lampung', 2019, 'Regional', '77167aea-eedb-477c-a4ab-8b9538077ab2', 'Meraih tempat ketiga dalam kategori sepak bola robot humanoid otonom pada kompetisi regional Sumatera yang dipusatkan di Lampung.', '2026-07-04 13:17:10.777297+00'),
	('1a4b7519-8028-4904-846f-d88b5461f621', 'Juara Harapan 1 KRSTI Tingkat Regional 1', 2020, 'Regional', 'ad649bf4-f483-4bee-b0b1-0468cb076aae', 'Mengamankan posisi harapan pertama regional pada masa kompetisi berbasis daring/hybrid Kontes Robot Seni Tari Indonesia.', '2026-07-04 13:17:10.777297+00'),
	('baa1d749-be05-4994-8442-006ffe72f836', 'Juara 3 KRSBI Humanoid Menggiring Bola Regional 1', 2020, 'Regional', '77167aea-eedb-477c-a4ab-8b9538077ab2', 'Meraih podium ketiga pada sub-kategori khusus penggiringan bola (dribbling task) secara otonom menggunakan robot humanoid berkaki di Regional 1.', '2026-07-04 13:17:10.777297+00'),
	('22f4db27-d505-4f4e-b0f0-c685b5586cc7', 'Peringkat 6 KRSBI Beroda Regional 1', 2020, 'Regional', '9c687745-1b13-44cd-9455-3acac8b2e1b3', 'Mengamankan posisi 6 besar pada kompetisi regional yang menguji ketahanan sistem kendali robot jarak jauh selama masa pembatasan fisik.', '2026-07-04 13:17:10.777297+00'),
	('e4da7ef2-cbe1-4f16-a747-3b531c7a5bb3', 'Juara 1 KRSTI Tingkat Regional I', 2022, 'Regional', 'ad649bf4-f483-4bee-b0b1-0468cb076aae', 'Kembali merebut takhta Juara Pertama di Regional I berkat keunggulan pemrosesan citra untuk sinkronisasi robot seni tari terhadap ritme musik.', '2026-07-04 13:17:10.777297+00'),
	('fc5fb513-6fc4-4059-bf6d-8e16f6f17c3c', 'Juara 3 KRSBI Humanoid Tingkat Regional I', 2022, 'Regional', '77167aea-eedb-477c-a4ab-8b9538077ab2', 'Meraih peringkat ketiga regional Sumatera lewat optimasi algoritma kecerdasan buatan untuk deteksi bola dan penentuan posisi gawang.', '2026-07-04 13:17:10.777297+00'),
