	('6fe39c31-3c0e-4f22-b1f5-4485ce8f35d8', 'Juara Harapan 1 KRSTI Tingkat Regional I', 2024, 'Regional', 'ad649bf4-f483-4bee-b0b1-0468cb076aae', 'Menjaga konsistensi performa di jajaran elit dengan menempati posisi harapan pertama pada ajang regional Kontes Robot Seni Tari Indonesia.', '2026-07-04 13:17:10.777297+00'),
	('20d78a56-3552-41c9-93bd-3fd0c627c5ab', 'Finalis Kontes Robot ABU Indonesia (KRAI) Tingkat Nasional', 2025, 'Nasional', '5a1995dd-635e-411f-898e-15353d60c8ca', 'Keberhasilan lolos sebagai finalis nasional dan mengirimkan delegasi tim utama KRAI untuk bertanding dalam ajang bergengsi Kontes Robot Indonesia (KRI) 2025 yang diselenggarakan di Institut Teknologi Bandung (ITB).', '2026-07-04 13:20:28.054587+00');
